<?php use App\Support\Helpers; ?>
<?php $analysis = $pending['analysis']; ?><h1>Revisar importación</h1><section class="card"><p><strong><?= Helpers::h($pending['filename']) ?></strong> · <?= $analysis['rows'] ?> filas · <?= count($analysis['headers']) ?> columnas · delimitador: <?= Helpers::h($analysis['delimiter'] === "\t" ? 'tabulador' : $analysis['delimiter']) ?></p><?php if ($analysis['errors']): ?><div class="alert error"><strong>Errores críticos</strong><ul><?php foreach ($analysis['errors'] as $error): ?><li><?= Helpers::h($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?><?php if ($analysis['warnings']): ?><div class="alert"><ul><?php foreach ($analysis['warnings'] as $warning): ?><li><?= Helpers::h($warning) ?></li><?php endforeach; ?></ul></div><?php endif; ?><table><thead><tr><th>Columna</th><th>Tipo detectado</th><th>Candidata a clave</th></tr></thead><tbody><?php foreach ($analysis['headers'] as $header): ?><tr><td><?= Helpers::h($header) ?></td><td><?= Helpers::h($analysis['types'][$header]) ?></td><td><?= array_key_exists($header, $analysis['candidates']) ? ($analysis['candidates'][$header] ? 'Única' : 'No única') : '—' ?></td></tr><?php endforeach; ?></tbody></table></section>
<?php if (!$analysis['errors']): ?><section class="card"><form method="post" action="/admin/import/confirm"><input type="hidden" name="csrf" value="<?= Helpers::h($csrf) ?>"><h2>Identificación de registros</h2><p>Selecciona una o varias columnas que formen una clave única. La unicidad se validará de nuevo antes de confirmar.</p><fieldset><?php foreach ($analysis['headers'] as $header): ?><label class="check"><input type="checkbox" name="key_columns[]" value="<?= Helpers::h($header) ?>" <?= in_array($header, $keyColumns, true) ? 'checked' : '' ?>> <?= Helpers::h($header) ?><?= array_key_exists($header, $analysis['candidates']) ? ($analysis['candidates'][$header] ? ' (candidata única)' : ' (candidata no única)') : '' ?></label><?php endforeach; ?></fieldset><label class="check"><input type="checkbox" name="replace_mode" <?= $replaceMode ? 'checked' : '' ?>> Reemplazar dataset sin clave lógica (solo si no hay identidad estable)</label><button>Confirmar importación</button></form></section><?php endif; ?>
